<template>
  <div class="user-container">
    <h2>用户管理列表</h2>

    <!-- 添加表单 -->
    <div class="add-form">
      <input v-model="user.username" placeholder="用户名" />
      <input v-model="user.age" placeholder="年龄" type="number" />
      <input v-model="user.phone" placeholder="手机号" />
      <button @click="addUser">添加用户</button>
    </div>

    <!-- 数据列表 -->
    <table class="user-table">
      <thead>
        <tr>
          <th>ID</th>
          <th>用户名</th>
          <th>年龄</th>
          <th>手机号</th>
          <th>操作</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="item in userList" :key="item.id">
          <td>{{ item.id }}</td>
          <td>{{ item.username }}</td>
          <td>{{ item.age }}</td>
          <td>{{ item.phone }}</td>
          <td>
            <button class="del-btn" @click="deleteUser(item.id)">删除</button>
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import axios from 'axios'

// 列表数据
const userList = ref([])
// 表单数据
const user = ref({
  username: '',
  age: '',
  phone: ''
})

// 页面加载时获取列表
onMounted(() => {
  getUserList()
})

// 获取列表
const getUserList = async () => {
  const res = await axios.get('http://localhost:8080/user/list')
  userList.value = res.data
}

// 添加用户
const addUser = async () => {
  await axios.post('http://localhost:8080/user/add', user.value)
  alert('添加成功')
  getUserList()
  user.value = { username: '', age: '', phone: '' }
}

// 删除用户
const deleteUser = async (id) => {
  if (!confirm('确定删除？')) return
  await axios.get(`http://localhost:8080/user/delete/${id}`)
  alert('删除成功')
  getUserList()
}
</script>

